    'home.lang.heading': '🖊️ Почему традиционный китайский?',
    'home.lang.p1':
      'Taiwan.md выбирает <strong>традиционный китайский</strong> как язык по умолчанию — это не только техническое решение, это культурный манифест.',
    'home.lang.p2':
      'Традиционный китайский — одна из древнейших систем письма, всё ещё используемых в повседневной жизни, а Тайвань — единственная основная страна в мире, где традиционный китайский является официальным письмом. Каждый штрих несёт тысячелетнюю культурную память. Открывая этот сайт и видя иероглифы, вы читаете не просто текст, а живое культурное наследие.',
